  function freshSvg(entry, cls) {
    var svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
    svg.setAttribute("viewBox", entry.vb);
    svg.setAttribute("preserveAspectRatio", "xMidYMid meet");
    if (cls) svg.setAttribute("class", cls);
    svg.style.width = "100%";
    svg.style.height = "100%";
    svg.style.display = "block";
    svg.innerHTML = entry.inner;
    return svg;
  }
  function mount(name, target, opts) {
    opts = opts || {};
    var entry = CATALOG[name];
    if (!entry) throw new Error("SatchidaAnatomy: unknown organ " + name);
    var el = typeof target === "string" ? document.getElementById(target) : target;
    if (!el) throw new Error("SatchidaAnatomy: missing target for " + name);
    el.innerHTML = "";
    var svg = freshSvg(entry);
    if (opts.filter) svg.style.filter = opts.filter;
    if (opts.opacity != null) svg.style.opacity = opts.opacity;
    var wrap = document.createElement("div");
    wrap.className = "sa-organ";
    wrap.style.cssText = "position:relative;width:100%;height:100%;";
    if (opts.glow) wrap.style.filter = "drop-shadow(0 0 6px " + opts.glow + ")";
    wrap.appendChild(svg);
    if (opts.label) {
      var lbl = document.createElement("div");
      lbl.className = "sa-organ-label";
      lbl.textContent = opts.label;
      lbl.style.cssText = "position:absolute;left:0;right:0;bottom:2px;text-align:center;font-size:10px;font-weight:700;letter-spacing:.04em;color:#e2e8f0;text-shadow:0 1px 3px rgba(0,0,0,.8);pointer-events:none;";
      wrap.appendChild(lbl);
    }
    el.appendChild(wrap);
    el.setAttribute("data-sa-organ", name);
    var handle = {
      name: name, el: wrap, svg: svg,
      setVariant: function (newName) {
        var e2 = CATALOG[newName];
        if (!e2) return false;
        var fresh = freshSvg(e2, svg.getAttribute("class"));
        fresh.style.filter = svg.style.filter;
        fresh.style.opacity = svg.style.opacity;
        wrap.replaceChild(fresh, svg);
        svg = fresh; this.svg = svg; return true;
      },
      setFilter: function (css) { svg.style.filter = css || "none"; },
      setOpacity: function (v) { svg.style.opacity = v == null ? 1 : v; },
      glow: function (color) { wrap.style.filter = color ? "drop-shadow(0 0 6px " + color + ")" : "none"; }
    };
    return handle;
  }
  function variants(name) {
    var groups = {
      liver: ["liver-healthy", "liver", "liver-fibrotic", "liver-cirrhotic"],
      vein: ["vein-healthy", "vein", "vein-varicose"]
    };
    return groups[name] || [name];
  }
  return { CATALOG: CATALOG, mount: mount, variants: variants, list: Object.keys(CATALOG) };
